class RehearsalStopped(RuntimeError):pass

def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def ident(value):return '"'+str(value).replace('"','""')+'"'
def literal(value):return "'"+str(value).replace("'","''")+"'"

def read_inputs(backup_folder,data_only=False):
    project,dest=settings(backup_folder)
    snapshots=[]
    for path in (dest/'data').glob('*/manifest.json'):
        if path.parent.name.startswith('.'):continue
        try:m=json.loads(path.read_text(encoding='utf-8'))
        except (OSError,ValueError):continue
        if m.get('complete') is True and m.get('source','').rstrip('/')=='https://'+project+'.supabase.co':snapshots.append(path.parent)
    if not snapshots:raise RehearsalStopped('No complete matching data backup found.')
    snapshot=sorted(snapshots)[-1];manifest=verify(snapshot,require_home_quest=True)
    tables={}
    allowed=REQUIRED|HOME_QUEST|{'member_pins','al_work_receipts'}
    for entry in manifest['tables']:
        table=Path(entry['path']).stem
        if entry['path']!=table+'.json' or table not in allowed:raise RehearsalStopped('Unexpected table in the school backup.')
        tables[table]=json.loads((snapshot/entry['path']).read_text(encoding='utf-8'))
    if not tables.get('households') or not {'kid1','kid2'}.issubset({r.get('id') for r in tables.get('al_kids',[])}):
        raise RehearsalStopped('The selected snapshot does not contain the household and both school profiles.')
    if 'member_pins' not in tables:
        supplements=[]
        for path in (dest/'recovery-supplements').glob('pins-*/manifest.json'):
            try:m=json.loads(path.read_text(encoding='utf-8'))
            except (OSError,ValueError):continue
            if m.get('format')=='forge-member-pins-supplement-v1' and m.get('complete') is True and m.get('source','').rstrip('/')=='https://'+project+'.supabase.co':supplements.append((path,m))
        if not supplements:raise RehearsalStopped('The private PIN supplement was not found.')
        path,m=sorted(supplements,key=lambda item:str(item[0]))[-1];entry=m['table']
        if entry['path']!='member_pins.json' or sha(path.parent/entry['path'])!=entry['sha256']:
            raise RehearsalStopped('PIN supplement checksum/path failed.')
        pins=json.loads((path.parent/entry['path']).read_text(encoding='utf-8'))
        if not isinstance(pins,list) or len(pins)!=entry['rows']:raise RehearsalStopped('PIN supplement count failed.')
        tables['member_pins']=pins
    structures=[]
    for path in (dest/'database-structure').glob('*/manifest.json'):
        if path.parent.name.startswith('.'):continue
        try:m=json.loads(path.read_text(encoding='utf-8'))
        except (OSError,ValueError):continue
        if m.get('format')=='forge-structure-export-v1' and m.get('complete') is True and m.get('project_ref')==project:structures.append((path,m))
    if not structures:raise RehearsalStopped('The private structure export was not found.')
    path,m=sorted(structures,key=lambda item:str(item[0]))[-1];sql={}
    if {e['path'] for e in m['files']}!={'application.sql','managed-structure.sql','roles.sql'}:
        raise RehearsalStopped('Unexpected structure export files.')
    for entry in m['files']:
        file=path.parent/entry['path']
        if sha(file)!=entry['sha256'] or file.stat().st_size!=entry['bytes']:raise RehearsalStopped('Structure checksum failed.')
        sql[entry['path']]=file.read_text(encoding='utf-8')
    # Public URLs remain references only. Do not fetch them during this offline test.
    backed={e['path'][7:] for e in manifest['files'] if e['path'].startswith('_files/')}
    def walk(value):
        if isinstance(value,dict):
            for v in value.values():yield from walk(v)
        elif isinstance(value,list):
            for v in value:yield from walk(v)
        elif isinstance(value,str):yield value
    missing_paths=set();missing_references=0
    for table in ('al_assignments','al_journal','al_reflections'):
        for value in walk(tables.get(table,[])):
            if not value.startswith('https://'+project+'.supabase.co/storage/v1/object/'):continue
            url=urlparse(value);match=re.match(r'^/storage/v1/object/(?:public|sign)/lesson-uploads/(.+)$',url.path)
            if match and unquote(match.group(1)) not in backed:
                missing_references+=1;missing_paths.add(unquote(match.group(1)))
    if missing_paths and not data_only:
        raise RehearsalStopped('A saved school upload reference has no matching backed-up file.')
    # These fields describe rehearsal coverage only. Never write them into the source
    # manifest, change a stored URL/completion flag, or represent missing media as recovered.
    manifest=dict(manifest)
    manifest['rehearsal_media_coverage']={'missing_references':missing_references,'missing_unique_paths':len(missing_paths),
      'data_only_requested':bool(data_only),'all_references_backed_up':not missing_paths,'playback_tested':False}
    return project,dest,snapshot,manifest,tables,sql

def clean_env(home,endpoint):
    env={k:v for k,v in os.environ.items() if not k.upper().startswith(('SUPABASE_','PG','DOCKER_HOST','DOCKER_CONTEXT','DOCKER_TLS','DOCKER_CERT'))}
    env['SUPABASE_HOME']=str(home);env['DOCKER_HOST']=endpoint
    return env

def source_major(sql,confirmed=None):
    # CLI exports may omit pg_dump comments. Never infer the hosted version from
    # a fresh local config's default. An owner-confirmed server_version is a valid
    # explicit source when the comment is absent.
    match=re.search(r'(?im)^\s*--\s*Dumped from database version\s+(\d+)(?:\.|\s|$)',sql)
    detected=int(match.group(1)) if match else None
    if confirmed is not None and confirmed not in (15,17):
        raise RehearsalStopped('Unsupported explicitly confirmed source database version.')
    if detected is not None and confirmed is not None and detected!=confirmed:
        raise RehearsalStopped('The confirmed server version conflicts with the structure export. No database was started.')
    major=confirmed if confirmed is not None else detected
    if major not in (15,17):
        raise RehearsalStopped('Source version is absent or unsupported. Confirm server_version in the SQL Editor, then provide --source-major; do not repeat the backup.')
    return major

class LocalDatabase:
    def __init__(self,cli,workspace,log,runner=subprocess.run,major=17):
        self.cli=Path(cli).resolve();self.workspace=Path(workspace);self.log=Path(log);self.runner=runner
        self.project='forge-rehearsal-'+uuid.uuid4().hex[:12]
        self.volume='supabase_db_'+self.project;self.container_name='supabase_db_'+self.project
        self.network='forge-rehearsal-net-'+uuid.uuid4().hex[:12];self.container=None
        self.major=major
        self.endpoint='npipe:////./pipe/docker_engine' if os.name=='nt' else 'unix:///var/run/docker.sock'
        self.env=clean_env(self.workspace/'private-cli-home',self.endpoint)
        self.docker=shutil.which('docker')
        if not self.docker or not self.cli.is_file():raise RehearsalStopped('Docker or the portable Supabase CLI is missing.')
    def call(self,args,data=None,timeout=1800,allow_failure=False):
        try:
            r=self.runner(args,cwd=str(self.workspace),env=self.env,input=data if data is not None else b'',
                capture_output=True,timeout=timeout)
        except (OSError,subprocess.TimeoutExpired):raise RehearsalStopped('A local rehearsal command could not finish; no hosted command was run.') from None
        with self.log.open('ab') as f:
            # Do not log SQL inputs or successful row-query output.
            if r.stderr:f.write(r.stderr if isinstance(r.stderr,bytes) else r.stderr.encode())
            if r.returncode and r.stdout:f.write(r.stdout if isinstance(r.stdout,bytes) else r.stdout.encode())
        if r.returncode and not allow_failure:raise RehearsalStopped('Local rehearsal stopped. Private diagnostics were saved beside the report.')
        return r
    def dock(self,args,**kwargs):return self.call([self.docker,'--host='+self.endpoint,*args],**kwargs)
    def cli_call(self,args):
        if args not in (['init'],['db','start']):raise RehearsalStopped('Unsupported rehearsal command.')
        return self.call([str(self.cli),*args,'--workdir',str(self.workspace),'--network-id',self.network])
    def inspect(self):
        r=self.dock(['inspect',self.container_name]);x=json.loads(r.stdout)[0]
        if x.get('Name')!='/'+self.container_name:raise RehearsalStopped('Unexpected local container identity.')
        return x
    def assert_offline(self):
        x=self.inspect()
        if x['Id']!=self.container or x.get('NetworkSettings',{}).get('Networks'):
            raise RehearsalStopped('Rehearsal container is not isolated; refusing to load or query private data.')
        options=json.loads(self.dock(['volume','inspect',self.volume]).stdout)[0].get('Options') or {}
        if options.get('type')!='tmpfs' or options.get('device')!='tmpfs':
            raise RehearsalStopped('Expected temporary RAM-backed database volume; private data was not loaded.')
        data_mounts=[m for m in x.get('Mounts',[]) if m.get('Name')==self.volume]
        if not data_mounts:raise RehearsalStopped('Expected rehearsal data mount is missing.')
    def start(self):
        if os.name=='nt':
            context=self.call([self.docker,'context','inspect','desktop-linux','--format','{{.Endpoints.docker.Host}}'],allow_failure=True)
            endpoint=context.stdout.decode('utf-8').strip() if not context.returncode else ''
            if endpoint in ('npipe:////./pipe/docker_engine','npipe:////./pipe/dockerDesktopLinuxEngine'):
                self.endpoint=endpoint;self.env['DOCKER_HOST']=endpoint
        info=json.loads(self.dock(['info','--format','{{json .}}']).stdout)
        if info.get('OSType')!='linux':raise RehearsalStopped('Docker must be using Linux containers.')
        if self.dock(['container','inspect',self.container_name],allow_failure=True).returncode==0:
            raise RehearsalStopped('Rehearsal name already exists; no existing container will be changed.')
        for kind,name in (('volume',self.volume),('network',self.network)):
            if self.dock([kind,'inspect',name],allow_failure=True).returncode==0:
                raise RehearsalStopped('A rehearsal resource name already exists; it will not be reused.')
        self.cli_call(['init'])
        config=self.workspace/'supabase/config.toml';text=config.read_text(encoding='utf-8')
        text=re.sub(r'(?m)^project_id\s*=.*$', 'project_id = "'+self.project+'"',text,count=1)
        with socket.socket() as sock:sock.bind(('127.0.0.1',0));port=sock.getsockname()[1]
        text=re.sub(r'(?m)^port\s*=\s*54322\s*$', 'port = '+str(port),text,count=1)
        text=text.replace('[db]\n','[db]\npassword = "'+uuid.uuid4().hex+uuid.uuid4().hex+'"\n',1)
        text=re.sub(r'(?m)^major_version\s*=\s*\d+\s*$', 'major_version = '+str(self.major),text,count=1)
        config.write_text(text,encoding='utf-8')
        cached=self.dock(['image','ls','--format','{{json .}}']).stdout.decode('utf-8')
        tags=[]
        for line in cached.splitlines():
            image=json.loads(line);tag=image.get('Tag','');repo=image.get('Repository','')
            if repo.endswith('/supabase/postgres') or repo=='supabase/postgres':
                if re.fullmatch(str(self.major)+r'\.\d+\.\d+\.\d+',tag):tags.append(tag)
        if not tags:raise RehearsalStopped('A cached matching Supabase database image was not found. No private data was loaded.')
        version=sorted(tags,key=lambda t:tuple(map(int,t.split('.'))))[-1]
        cache=config.parent/'.temp';cache.mkdir(exist_ok=True);(cache/'postgres-version').write_text(version+'\n',encoding='utf-8')
        self.dock(['volume','create','--driver','local','--opt','type=tmpfs','--opt','device=tmpfs','--opt','o=size=2147483648',
            '--label','forge.rehearsal='+self.project,self.volume])
        # Docker Desktop must reach the empty database's published local health
        # port during bootstrap. Disconnect every network and assert isolation
        # below BEFORE loading application definitions or family records.
        self.dock(['network','create','--opt','com.docker.network.bridge.host_binding_ipv4=127.0.0.1',
            '--label','forge.rehearsal='+self.project,self.network])
        print('Starting a new empty local database using a cached database image...',flush=True)
        self.cli_call(['db','start'])
        x=self.inspect();self.container=x['Id']
        for network in list(x.get('NetworkSettings',{}).get('Networks',{})):
            self.dock(['network','disconnect',network,self.container])
        self.assert_offline()
        # Confirm the actual database directory uses the verified tmpfs mount.
        directory=self.query('SHOW data_directory;',raw=True).strip()
        mount=next(m['Destination'] for m in self.inspect()['Mounts'] if m.get('Name')==self.volume)
        if directory!=mount and not directory.startswith(mount.rstrip('/')+'/'):
            raise RehearsalStopped('Database files are outside the temporary data mount; private data was not loaded.')
        self.query("ALTER SYSTEM SET log_min_error_statement='panic'; SELECT pg_reload_conf();",raw=True)
        baseline=self.query("SELECT jsonb_build_object('users',to_regclass('auth.users') IS NOT NULL,'uid',to_regprocedure('auth.uid()') IS NOT NULL,'roles',(SELECT count(*) FROM pg_roles WHERE rolname IN ('anon','authenticated')));")
        if not baseline['users'] or not baseline['uid'] or baseline['roles']!=2:
            raise RehearsalStopped('Local Supabase authentication baseline is missing. No private records were loaded.')
    def query(self,sql,raw=False):
        self.assert_offline()
        # Supabase's postgres role is deliberately not a PostgreSQL superuser.
        # Administrative restore operations (logging, roles, replication mode)
        # need supabase_admin, exclusively inside this owned, offline container.
        r=self.dock(['exec','-i',self.container,'psql','-X','-w','-U','supabase_admin','-d','postgres','-v','ON_ERROR_STOP=1','-qtA','-f','-'],data=sql.encode('utf-8'))
        out=r.stdout.decode('utf-8')
        if raw:return out
        if out.strip() in ('t','f'):return out.strip()=='t'
        return json.loads(out.strip())
    def stop(self):
        # Stop only the immutable ID captured from our own newly-created database.
        if self.container:
            self.dock(['stop','--time','10',self.container],timeout=60)
            self.dock(['rm',self.container],timeout=60)
            self.dock(['volume','rm',self.volume],timeout=60)
            self.dock(['network','rm',self.network],timeout=60)

def insert_sql(tables):
    statements=['BEGIN; SET LOCAL session_replication_role=replica; SET LOCAL standard_conforming_strings=on; SET LOCAL timezone=\'UTC\';']
    households=[r['id'] for r in tables['households']]
    for key in households:
        uuid.UUID(key)
        statements.append('INSERT INTO auth.users(id) VALUES('+literal(key)+'::uuid) ON CONFLICT(id) DO NOTHING;')
    for table,rows in tables.items():
        if table not in REQUIRED|HOME_QUEST|{'member_pins','al_work_receipts'}:raise RehearsalStopped('Unexpected restored table.')
        payload=json.dumps(rows,ensure_ascii=False,allow_nan=False,separators=(',',':'))
        statements.append('INSERT INTO public.'+ident(table)+' SELECT * FROM jsonb_populate_recordset(NULL::public.'+ident(table)+','+literal(payload)+'::jsonb);')
    statements.append('SET LOCAL session_replication_role=origin; COMMIT;')
    return '\n'.join(statements)

def check_rows(db,tables):
    counts={}
    for table,expected in tables.items():
        actual=db.query("SET timezone='UTC'; SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public."+ident(table)+' t;')
        key='member_id' if table=='member_pins' else ('household_id' if table=='al_settings' else 'id')
        def order(row):return str(row.get(key,''))
        if sorted(actual,key=order)!=sorted(expected,key=order):raise RehearsalStopped('Restored values/counts differ in '+table+'.')
        counts[table]=len(actual)
    return counts

def check_foreign_keys(db,tables):
    fks=db.query("""SELECT coalesce(jsonb_agg(x),'[]'::jsonb) FROM (
      SELECT sn.nspname AS src_schema,src.relname AS src_table,tn.nspname AS dst_schema,dst.relname AS dst_table,c.confmatchtype AS match,
        (SELECT jsonb_agg(a.attname ORDER BY k.n) FROM unnest(c.conkey) WITH ORDINALITY k(attnum,n) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.attnum) AS src_columns,
        (SELECT jsonb_agg(a.attname ORDER BY k.n) FROM unnest(c.confkey) WITH ORDINALITY k(attnum,n) JOIN pg_attribute a ON a.attrelid=c.confrelid AND a.attnum=k.attnum) AS dst_columns
      FROM pg_constraint c JOIN pg_class src ON src.oid=c.conrelid JOIN pg_namespace sn ON sn.oid=src.relnamespace
      JOIN pg_class dst ON dst.oid=c.confrelid JOIN pg_namespace tn ON tn.oid=dst.relnamespace
      WHERE c.contype='f' AND sn.nspname='public') x;""")
    checked=0
    for fk in fks:
        if fk['src_table'] not in tables:continue
        if fk['match']!='s':raise RehearsalStopped('A nonstandard foreign key requires an explicit restore review.')
        nonnull=' AND '.join('s.'+ident(c)+' IS NOT NULL' for c in fk['src_columns'])
        equals=' AND '.join('s.'+ident(a)+'=d.'+ident(b) for a,b in zip(fk['src_columns'],fk['dst_columns']))
        query='SELECT EXISTS(SELECT 1 FROM '+ident(fk['src_schema'])+'.'+ident(fk['src_table'])+' s WHERE '+nonnull+' AND NOT EXISTS(SELECT 1 FROM '+ident(fk['dst_schema'])+'.'+ident(fk['dst_table'])+' d WHERE '+equals+'));'
        if db.query(query):raise RehearsalStopped('A restored foreign-key relationship is incomplete.')
        checked+=1
    return checked

def check_household_reads(db,tables):
    targets=('al_assignments','al_questions','transactions','home_jobs')
    def read(role,claim,table):
        # Use the real baseline auth.uid() function with local request claims.
        return db.query('BEGIN; SET LOCAL ROLE '+ident(role)+'; SET LOCAL "request.jwt.claim.sub"='+literal(claim)+'; SELECT count(*)::int FROM public.'+ident(table)+'; ROLLBACK;',raw=True)
    def scalar_count(raw):
        matches=re.findall(r'(?m)^\d+$',raw)
        if len(matches)!=1:raise RehearsalStopped('Unexpected local role-check response.')
        return int(matches[0])
    for table in targets:
        if scalar_count(read('anon','',table))!=0:raise RehearsalStopped('Anonymous rows visible in restored '+table+'.')
        unknown=str(uuid.uuid4())
        if scalar_count(read('authenticated',unknown,table))!=0:raise RehearsalStopped('Cross-household rows visible in restored '+table+'.')
        for household in tables['households']:
            expected=sum(1 for row in tables[table] if row.get('household_id')==household['id'])
            if scalar_count(read('authenticated',household['id'],table))!=expected:
                raise RehearsalStopped('Own-household read failed in restored '+table+'.')
    return len(targets)

def rehearse(backup_folder,cli,runner=subprocess.run,data_only=False,confirmed_major=None):
    print('Verifying private backup, supplement, structure and file references locally...',flush=True)
    project,dest,snapshot,backup,tables,sql=read_inputs(backup_folder,data_only=data_only)
    media=backup['rehearsal_media_coverage']
    if media['missing_unique_paths']:
        print('Data-only rehearsal: '+str(media['missing_unique_paths'])+' unmatched attachment paths remain documented; none are removed or recovered.',flush=True)
    stamp=datetime.datetime.now().strftime('%Y-%m-%d_%H%M%S_%f');folder=dest/'restore-rehearsals'/stamp;folder.mkdir(parents=True,exist_ok=False)
    workspace=folder/'local-rehearsal';workspace.mkdir()
    major=source_major(sql['application.sql'],confirmed=confirmed_major)
    db=LocalDatabase(cli,workspace,folder/'PRIVATE-diagnostics.txt',runner,major=major)
    report={'format':'forge-local-restore-check-v1','complete':False,'full_project_restore_certified':False,
      'data_only_requested':bool(data_only),'media_coverage':media,
      'source_major':major,'source_version_confirmation':'owner SQL Editor check' if confirmed_major is not None else 'export comment',
      'limits':['Local database/data rehearsal only. Auth rows are local placeholders, not restored login accounts.',
       'No browser sign-in, media playback, Edge Functions/secrets, storage service or device worlds are certified.',
       'Managed schema reference export is not blindly loaded over the local baseline.',
       'Scoped school/money/quest data only. Other apps schema definitions may exist, but their data is not imported.',
       'Temporary RAM-backed database is stopped after checking. Private diagnostics/reports remain beside backups.']}
    try:
        report['stage']='local_database_setup'
        db.start()
        print('Database isolated. Restoring definitions and scoped records...',flush=True)
        report['stage']='structure_load'
        db.query(sql['roles.sql'],raw=True)
        db.query(sql['application.sql'],raw=True)
        report['stage']='scoped_data_load'
        db.query(insert_sql(tables),raw=True)
        report['stage']='value_comparison'
        counts=check_rows(db,tables)
        report['stage']='relationships'
        relationships=check_foreign_keys(db,tables)
        report['stage']='household_roles'
        role_tables=check_household_reads(db,tables)
        report['stage']='pin_consistency'
        mismatch=db.query('SELECT count(*)::int FROM public.members m WHERE m.has_pin IS DISTINCT FROM EXISTS(SELECT 1 FROM public.member_pins p WHERE p.member_id=m.id);')
        if mismatch:raise RehearsalStopped('PIN supplement and member snapshot do not agree; keep both for reconciliation.')
        report.update(complete=True,stage='data_checks_passed',table_counts=counts,foreign_keys_checked=relationships,role_tables_checked=role_tables,
          uploaded_files_checksums_verified=len(backup['files']),created_at=datetime.datetime.now(datetime.timezone.utc).isoformat())
    except Exception:
        print('Incomplete rehearsal stage: '+report['stage'],flush=True)
        raise
    finally:
        try:db.stop()
        except Exception:
            report['complete']=False;report['cleanup']='Could not confirm the isolated local container stopped.'
        (folder/'report.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
    if not report['complete']:raise RehearsalStopped('Local restore check is incomplete. Keep its private report and diagnostics.')
    print('Local data restore checks passed: '+str(len(counts))+' tables, '+str(relationships)+' relationships, '+str(role_tables)+' household-read checks.')
    if media['missing_unique_paths']:print('Unresolved media references remain: '+str(media['missing_unique_paths'])+' unmatched paths. This does not certify media recovery.')
    print('Login, media playback and full app recovery still require separate tests. Keep report/diagnostics private.')
    return report

def main():
    parser=argparse.ArgumentParser(description='Local database rehearsal; --data-only records known media gaps without certifying media recovery.')
    parser.add_argument('--data-only',action='store_true')
    parser.add_argument('--source-major',type=int,choices=(15,17),help='Use only after confirming the hosted server_version in the SQL Editor.')
    args=parser.parse_args()
    try:
        from tkinter import Tk,filedialog
        ui=Tk();ui.withdraw();folder=filedialog.askdirectory(title='Choose the existing folder containing backup.py and .env');ui.destroy()
        if not folder:raise RehearsalStopped('No folder selected; no rehearsal started.')
        cli=Path(__file__).with_name('supabase.exe')
        rehearse(folder,cli,data_only=args.data_only,confirmed_major=args.source_major)
    except RehearsalStopped as e:print('STOPPED: '+str(e));return 1
    except Exception:print('STOPPED: local rehearsal did not finish. Keep private diagnostics; no hosted restore was attempted.');return 1
    return 0
if __name__=='__main__':sys.exit(main())
